#include <assert.h>
#include "k16/debug.h"
int main(void){k16_machine_t m;k16_debug_io_t s;uint8_t f[2]={0x12,0x34};assert(k16_machine_init(&m,2u*1024u*1024u)==0);k16_machine_reset(&m);assert(k16_machine_key(&m,0x1c)==0);k16_machine_joystick(&m,1,0x15);k16_machine_mouse(&m,0,7,-3,1);assert(k16_machine_uart_receive(&m,'X')==0);assert(k16_machine_ethernet_receive(&m,f,2)==0);assert(k16_machine_ethernet_start_rx_dma(&m,0x1234)==0);k16_debug_io_snapshot(&m,&s);assert(s.key_count==1);assert(s.joy[1]==0x15);assert(s.mouse_x[0]==7&&s.mouse_y[0]==-3);assert(s.uart_rx_count==1);assert(s.eth_rx_ready&&s.eth_dma_active);assert(s.eth_dma_len==2&&s.eth_rx_addr==0x1234);assert(s.irq_pending&(K16_IRQ_KEYBOARD|K16_IRQ_CONTROLLER|K16_IRQ_UART_RX|K16_IRQ_ETH_RX));k16_machine_destroy(&m);return 0;}
